mapper.insert:
INSERT INTO alert_message_active (id, summary, description, labels, start_at, end_at, last_at, state, rule_id, project_id, module_id, endpoint_id, asset_id, dc_id, hash_key, remark, severity_id) VALUES
( #{item.id}, #{item.summary}, #{item.description}, #{item.labels}, #{item.startAt}, #{item.endAt}, #{item.lastAt}, #{item.state}, #{item.ruleId}, IFNULL(#{item.projectId}, -1), IFNULL(#{item.moduleId}, -1), IFNULL(#{item.endpointId}, -1), IFNULL(#{item.assetId}, -1), IFNULL(#{item.dcId}, -1), #{item.hashKey}, #{item.remark}, #{item.severityId} )
ON DUPLICATE KEY UPDATE id = VALUES(id), start_at = VALUES(start_at), last_at = VALUES(last_at), end_at = VALUES(end_at);

mapper.select:
SELECT am.*, ar.id as r_id , ar.name as r_name, ar.type as r_type, ar.trb_shot as r_trb_shot, ar.dashboard_id as r_dashboard_id, p.id as p_id, p.name as p_name, m.id as m_id, m.name as m_name, e.id as e_id, e.name as e_name, ass.id as ass_id, ass.name as ass_name, alsc.id as alsc_id, alsc.name as alsc_name, alsc.color as alsc_color, dc.id as dc_id, dc.name as dc_name FROM
${params.tableName} am
(select * from alert_message_active union all select * from alert_message_history union all select * from alert_message_silence) am
LEFT JOIN alert_rule ar ON am.rule_id = ar.id LEFT JOIN monitor_project p on am.project_id = p.id LEFT JOIN monitor_module m on am.module_id = m.id LEFT JOIN monitor_endpoint e on am.endpoint_id = e.id LEFT JOIN asset_asset ass on am.asset_id = ass.id LEFT JOIN alert_severity_conf alsc on am.severity_id = alsc.id LEFT JOIN dc dc on am.dc_id = dc.id
locate(#{params.ruleName} , ar.name)
AND am.severity_id in
#{id}
AND locate(#{params.summary} , am.summary)
AND locate(#{params.description} , am.description)
AND am.id in
#{id}
AND am.state=#{params.state}
AND am.start_at >= #{params.startAt}
AND am.start_at <= #{params.endAt}
AND am.rule_id in
#{id}
AND am.project_id in
#{id}
AND am.module_id in
#{id}
AND am.endpoint_id in
#{id}
AND am.asset_id in
#{id}
AND am.dc_id in
#{id}
AND locate(#{params.labels},am.labels)
AND locate(#{params.endpointName},e.name)
AND locate(#{params.assetName},ass.name)
AND locate(#{params.asset},ass.name)
AND am.ack=#{params.ack}
ORDER BY am.id

SELECT ${columnId} AS id, count(1) AS num FROM
${params.tableName} am
(select * from alert_message_active union all select * from alert_message_history union all select * from alert_message_silence) am
LEFT JOIN alert_rule ar ON am.rule_id = ar.id LEFT JOIN monitor_project p on am.project_id = p.id LEFT JOIN monitor_module m on am.module_id = m.id LEFT JOIN monitor_endpoint e on am.endpoint_id = e.id LEFT JOIN asset_asset ass on am.asset_id = ass.id LEFT JOIN alert_severity_conf alsc on am.severity_id = alsc.id LEFT JOIN dc dc on am.dc_id = dc.id
${columnId} is not null
AND locate(#{params.ruleName},ar.name)
AND am.severity_id in
#{id}
AND locate(#{params.summary},am.summary)
AND locate(#{params.description},am.description)
AND am.id in
#{id}
AND am.state=#{params.state}
AND am.start_at >= #{params.startAt}
AND am.start_at <= #{params.endAt}
AND am.rule_id in
#{id}
AND am.project_id in
#{id}
AND am.module_id in
#{id}
AND am.endpoint_id in
#{id}
AND am.asset_id in
#{id}
AND am.dc_id in
#{id}
AND locate(#{params.labels}, am.labels)
AND locate(#{params.endpointName},e.name )
AND locate(#{params.assetName},ass.name)
AND locate(#{params.asset},ass.name)
AND am.ack=#{params.ack}
GROUP BY ${columnId} ORDER BY num DESC

SELECT am.id, am.description, am.summary, am.labels, am.start_at, am.end_at, am.last_at, am.state, am.remark, am.hash_key, am.ack, ar.id AS r_id , ar.name AS r_name, ar.type AS r_type, ar.trb_shot AS r_trb_shot, p.id AS p_id, p.name AS p_name, m.id AS m_id, m.name AS m_name, e.id AS e_id, e.name AS e_name, ass.id AS ass_id, ass.name AS ass_name, alsc.id AS alsc_id, alsc.name AS alsc_name, alsc.color AS alsc_color, dc.id AS dc_id, dc.name AS dc_name FROM
${params.tableName} am
(SELECT * FROM alert_message_active UNION ALL SELECT * FROM alert_message_history UNION ALL SELECT * FROM alert_message_silence) am
LEFT JOIN alert_rule ar ON am.rule_id = ar.id LEFT JOIN alert_severity_conf alsc ON am.severity_id = alsc.id LEFT JOIN monitor_project p ON am.project_id = p.id LEFT JOIN monitor_module m ON am.module_id = m.id LEFT JOIN monitor_endpoint e ON am.endpoint_id = e.id LEFT JOIN asset_asset ass ON am.asset_id = ass.id LEFT JOIN dc dc ON am.dc_id = dc.id LEFT JOIN alert_silence_message_rel asmr ON am.id = asmr.message_id
am.id ${item.operator} #{item.value}
AND am.rule_id ${item.operator} #{item.value}
AND am.dc_id ${item.operator} #{item.value}
AND am.asset_id ${item.operator} #{item.value}
AND am.project_id ${item.operator} #{item.value}
AND am.module_id ${item.operator} #{item.value}
AND am.endpoint_id ${item.operator} #{item.value}
AND asmr.silence_conf_id ${item.operator} #{item.value}
AND am.severity_id ${item.operator} #{item.value}
AND ass.name = #{item}
AND locate(#{item},ass.name)
AND (
ass.name != #{item} OR ass.name IS NULL )
AND (
NOT locate(#{item},ass.name) OR ass.name IS NULL )
AND dc.name = #{item}
AND locate(#{item},dc.name)
AND (
dc.name != #{item} OR dc.name IS NULL )
AND (
NOT locate(#{item},dc.name) OR dc.name IS NULL )
AND p.name = #{item}
AND locate(#{item},p.name)
AND (
p.name != #{item} OR p.name IS NULL )
AND (
NOT locate(#{item},p.name) OR p.name IS NULL )
AND m.name = #{item}
AND locate(#{item},m.name)
AND (
m.name != #{item} OR m.name IS NULL )
AND (
NOT locate(#{item},m.name) OR m.name IS NULL )
AND e.name = #{item}
AND locate(#{item},e.name)
AND (
e.name != #{item} OR e.name IS NULL )
AND (
NOT locate(#{item},e.name) OR e.name IS NULL )
AND ar.name = #{item}
AND locate(#{item},ar.name)
AND ar.name != #{item}
AND NOT locate(#{item},ar.name)
AND alsc.name = #{item}
AND locate(#{item},alsc.name)
AND alsc.name != #{item}
AND NOT locate(#{item},alsc.name)
AND am.start_at >= #{params.startAt[0]}
AND am.start_at <= #{params.endAt[0]}
AND (locate(#{params.q} , am.summary) OR locate(#{params.q} , am.description) OR locate(#{params.q},am.labels))
